const EXTRA_FORMS = {"force":"forced","begin":"begins","claim":"claims","approach":"approached","pop":"popped","jump":"jumped","load":"loaded","crash":"crashed","invite":"inviting","principle":"principles","steal":"stole","ear":"ears","adapt":"adapted","bail":"bailed","circle":"circled","cram":"crammed","reinvent":"reinvented","chord":"chords","complain":"complained","curate":"curates","recur":"recurs","binge":"binged","knit":"knitted","chamber":"chambers","linger":"lingered","oversee":"oversees","streamline":"streamlined","escalate":"escalated","postpone":"postponed","nag":"nags","redecorate":"redecorating","provoke":"provoked","broaden":"broadens","memorize":"memorized","disappear":"disappeared","distort":"distorts","flag":"flags","lodge":"lodged"};
